"""Static artifacts written by ``tuvl ship``.

``CHART_YAML`` and ``VALUES_YAML`` are ``string.Template`` sources ($name,
$version); ``DOCKERFILE`` takes the locked tuvl version at ``@TUVL_VERSION@``;
everything else is written verbatim — the Helm ``{{ }}`` templates must reach
disk untouched.
"""

DOCKERFILE = """\
# Production image for this tuvl project — generated by `tuvl ship`.
FROM ghcr.io/astral-sh/uv:python3.13-bookworm-slim AS builder
WORKDIR /app
ENV UV_COMPILE_BYTECODE=1 UV_LINK_MODE=copy UV_PYTHON_DOWNLOADS=never
COPY pyproject.toml uv.lock* ./
RUN uv sync --no-dev --no-install-project
# tuvl is pinned to the version recorded in tuvl.lock, with only the extras this project uses.
RUN uv pip install --python /app/.venv/bin/python "tuvl@TUVL_EXTRAS@==@TUVL_VERSION@"

FROM python:3.13-slim-bookworm
WORKDIR /app
RUN useradd --system --create-home --uid 1001 tuvl
COPY --from=builder --chown=tuvl:tuvl /app/.venv /app/.venv
COPY --chown=tuvl:tuvl . /app
LABEL io.tuvl.extras="@TUVL_EXTRA_NAMES@"
ENV PATH="/app/.venv/bin:$PATH" \\
    TUVL_PROJECT_DIR=/app \\
    TUVL_ENV=production
EXPOSE 8885
USER tuvl
HEALTHCHECK --interval=30s --timeout=5s --start-period=15s \\
    CMD python -c "import urllib.request; urllib.request.urlopen('http://127.0.0.1:8885/health')"
CMD ["tuvl", "serve", "app", "--project-dir", "/app", "--host", "0.0.0.0", "--port", "8885"]
"""

DOCKERIGNORE = """\
# tuvl: allowlist — generated by `tuvl ship`. Only runtime files enter the image; specs, task
# lists, tests, agent rules and skills, compose files and everything else stay out. Re-include a
# runtime file with `!path`; `tuvl ship` refuses development files (V027).
*
!pyproject.toml
!uv.lock
!config.yaml
!tuvl.lock
!models/
!workflows/
!agents/
!artifacts/
!datasources/
!llms/
!storage/
!federation/
!.tuvl/system.yaml
!.tuvl/telemetry.yaml
**/__pycache__
**/*.pyc
"""

CHART_YAML = """\
apiVersion: v2
name: $name
description: Helm chart for the $name tuvl project
type: application
version: 0.1.0
appVersion: "$version"
"""

VALUES_YAML = """\
# Default values for the $name chart — generated by `tuvl ship`.

# One Deployment serves HTTP and executes queued runs (`tuvl serve app --role all`).
# split: true runs an `api` Deployment (the Service target; executes only
# synchronous requests inline) and a `worker` Deployment that executes the
# queue — scale them independently.
split: false
replicaCount: 1
# Runs each pod executes at once.
concurrency: 8

worker:
  replicaCount: 2
  concurrency: 8

image:
  repository: $name
  tag: ""  # empty = chart appVersion
  pullPolicy: IfNotPresent

# uvicorn workers per pod; prefer replicaCount for horizontal scale.
workers: 1

# Shutdown: a pod gets SIGTERM, stops taking requests, lets open ones finish for gracefulTimeout
# seconds, then waits drainTimeout for running runs (a run still going is interrupted and another
# pod resumes it from its last checkpoint). terminationGracePeriodSeconds must exceed their sum.
gracefulTimeout: 20
drainTimeout: 20
terminationGracePeriodSeconds: 60

# Proxies whose X-Forwarded-For header is trusted, as IPs or CIDRs: set your ingress controller's
# network so `--allow-host` and the logs see the real client. Empty trusts only 127.0.0.1; "*"
# trusts every sender, which lets a client spoof its address.
forwardedAllowIps: ""

# Restart each uvicorn worker after this many requests (0 = never).
limitMaxRequests: 0

# Pod hardening. readOnlyRootFilesystem is off because some admin features write under /app;
# turn it on once you know yours do not (a writable /tmp is mounted when it is on).
securityContext:
  runAsNonRoot: true
  runAsUser: 1001
  runAsGroup: 1001
  allowPrivilegeEscalation: false
  readOnlyRootFilesystem: false
  capabilities:
    drop: ["ALL"]
  seccompProfile:
    type: RuntimeDefault

# Plain (non-secret) environment for the engine container.
# Browser apps on another origin: TUVL_CORS_ORIGINS: "https://app.example.com" (or spec.api.cors_origins).
env:
  POSTGRES_HOST: postgres
  POSTGRES_PORT: "5432"
  POSTGRES_DB: $name
  POSTGRES_USER: postgres
$extra_env
# Existing Secret applied via envFrom. Must hold POSTGRES_PASSWORD,
# TUVL_SIGNING_KEY (tuvl generate key) and the models' variables:
#   $model_secrets
# (a production engine refuses to start while one is missing)
#   kubectl create secret generic $name-env --from-env-file=.env
existingSecret: $name-env

service:
  type: ClusterIP
  port: 80

resources: {}

# Laya decision server (laya-serve) for `decide` agents with `provider: laya`.
# Runs as its own Deployment; the engine reaches it at http://<fullname>-laya:8000.
# If the existing Secret holds LAYA_API_KEY, the server requires it as a bearer token.
laya:
  enabled: $laya_enabled
  replicaCount: 1
  image:
    repository: $laya_repository
    tag: "$laya_tag"
    pullPolicy: IfNotPresent
  env:
    LAYA_THREADS: "2"
  # $laya_memory_note The -en image serves English only; `model: auto` or
  # `multilingual` needs the full image.
  resources:
    requests:
      cpu: "1"
      memory: $laya_memory_request
    limits:
      memory: $laya_memory_limit

# `kind: Storage` stores with provider: local keep their files on one persistent volume, mounted
# at each store's root. With `split: true` the API and worker pods share it, so use a
# ReadWriteMany class. Cloud stores need no volume.
storage:
  local:
    enabled: $storage_enabled
    size: 10Gi
    storageClass: ""
    accessMode: ReadWriteOnce
    existingClaim: ""
    mounts: $storage_mounts

nameOverride: ""
fullnameOverride: ""
nodeSelector: {}
tolerations: []
affinity: {}
"""

HELPERS_TPL = """\
{{- define "app.name" -}}
{{- default .Chart.Name .Values.nameOverride | trunc 63 | trimSuffix "-" }}
{{- end }}

{{- define "app.fullname" -}}
{{- if .Values.fullnameOverride }}
{{- .Values.fullnameOverride | trunc 63 | trimSuffix "-" }}
{{- else }}
{{- $name := default .Chart.Name .Values.nameOverride }}
{{- if contains $name .Release.Name }}
{{- .Release.Name | trunc 63 | trimSuffix "-" }}
{{- else }}
{{- printf "%s-%s" .Release.Name $name | trunc 63 | trimSuffix "-" }}
{{- end }}
{{- end }}
{{- end }}

{{- define "app.labels" -}}
helm.sh/chart: {{ printf "%s-%s" .Chart.Name .Chart.Version }}
{{ include "app.selectorLabels" . }}
app.kubernetes.io/version: {{ .Chart.AppVersion | quote }}
app.kubernetes.io/managed-by: {{ .Release.Service }}
{{- end }}

{{- define "app.selectorLabels" -}}
app.kubernetes.io/name: {{ include "app.name" . }}
app.kubernetes.io/instance: {{ .Release.Name }}
{{- end }}

{{- define "app.httpRole" -}}
{{- if .Values.split }}api{{ else }}all{{ end }}
{{- end }}
"""

DEPLOYMENT_YAML = """\
{{- define "app.deployment" -}}
{{- $root := .root }}
apiVersion: apps/v1
kind: Deployment
metadata:
  name: {{ include "app.fullname" $root }}{{ .suffix }}
  labels:
    {{- include "app.labels" $root | nindent 4 }}
    app.kubernetes.io/component: {{ .role }}
spec:
  replicas: {{ .replicas }}
  selector:
    matchLabels:
      {{- include "app.selectorLabels" $root | nindent 6 }}
      app.kubernetes.io/component: {{ .role }}
  template:
    metadata:
      labels:
        {{- include "app.selectorLabels" $root | nindent 8 }}
        app.kubernetes.io/component: {{ .role }}
    spec:
      terminationGracePeriodSeconds: {{ $root.Values.terminationGracePeriodSeconds }}
      {{- if $root.Values.storage.local.enabled }}
      securityContext:
        fsGroup: 1001
      {{- end }}
      containers:
        - name: {{ $root.Chart.Name }}
          image: "{{ $root.Values.image.repository }}:{{ $root.Values.image.tag | default $root.Chart.AppVersion }}"
          imagePullPolicy: {{ $root.Values.image.pullPolicy }}
          securityContext:
            {{- toYaml $root.Values.securityContext | nindent 12 }}
          lifecycle:
            preStop:
              exec:
                command: ["sleep", "5"]
          args:
            - tuvl
            - serve
            - app
            - --project-dir
            - /app
            - --host
            - 0.0.0.0
            - --port
            - "8885"
            - --workers
            - {{ $root.Values.workers | quote }}
            - --role
            - {{ .role }}
            - --concurrency
            - {{ .concurrency | quote }}
            - --graceful-timeout
            - {{ $root.Values.gracefulTimeout | quote }}
            - --drain-timeout
            - {{ $root.Values.drainTimeout | quote }}
            {{- if $root.Values.forwardedAllowIps }}
            - --forwarded-allow-ips
            - {{ $root.Values.forwardedAllowIps | quote }}
            {{- end }}
            {{- if $root.Values.limitMaxRequests }}
            - --limit-max-requests
            - {{ $root.Values.limitMaxRequests | quote }}
            {{- end }}
          ports:
            - name: http
              containerPort: 8885
              protocol: TCP
          {{- if $root.Values.existingSecret }}
          envFrom:
            - secretRef:
                name: {{ $root.Values.existingSecret }}
          {{- end }}
          {{- if or $root.Values.env ($root.Values.laya).enabled }}
          env:
            {{- range $key, $value := $root.Values.env }}
            - name: {{ $key }}
              value: {{ $value | quote }}
            {{- end }}
            {{- if ($root.Values.laya).enabled }}
            - name: LAYA_API_BASE
              value: "http://{{ include "app.fullname" $root }}-laya:8000"
            {{- end }}
          {{- end }}
          readinessProbe:
            httpGet:
              path: /health
              port: http
            initialDelaySeconds: 5
            periodSeconds: 10
          livenessProbe:
            httpGet:
              path: /health
              port: http
            initialDelaySeconds: 15
            periodSeconds: 20
          {{- if or $root.Values.storage.local.enabled $root.Values.securityContext.readOnlyRootFilesystem }}
          volumeMounts:
            {{- if $root.Values.securityContext.readOnlyRootFilesystem }}
            - name: tmp
              mountPath: /tmp
            {{- end }}
            {{- if $root.Values.storage.local.enabled }}
            {{- range $root.Values.storage.local.mounts }}
            - name: storage
              mountPath: {{ .path }}
              subPath: {{ .subPath }}
            {{- end }}
            {{- end }}
          {{- end }}
          resources:
            {{- toYaml $root.Values.resources | nindent 12 }}
      {{- if or $root.Values.storage.local.enabled $root.Values.securityContext.readOnlyRootFilesystem }}
      volumes:
        {{- if $root.Values.securityContext.readOnlyRootFilesystem }}
        - name: tmp
          emptyDir: {}
        {{- end }}
        {{- if $root.Values.storage.local.enabled }}
        - name: storage
          persistentVolumeClaim:
            claimName: {{ $root.Values.storage.local.existingClaim | default (printf "%s-storage" (include "app.fullname" $root)) }}
        {{- end }}
      {{- end }}
      {{- with $root.Values.nodeSelector }}
      nodeSelector:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- with $root.Values.tolerations }}
      tolerations:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- with $root.Values.affinity }}
      affinity:
        {{- toYaml . | nindent 8 }}
      {{- end }}
{{- end }}

{{- include "app.deployment" (dict "root" . "role" (include "app.httpRole" .) "suffix" "" "replicas" .Values.replicaCount "concurrency" .Values.concurrency) }}
{{- if .Values.split }}
---
{{ include "app.deployment" (dict "root" . "role" "worker" "suffix" "-worker" "replicas" .Values.worker.replicaCount "concurrency" .Values.worker.concurrency) }}
{{- end }}
"""

SERVICE_YAML = """\
apiVersion: v1
kind: Service
metadata:
  name: {{ include "app.fullname" . }}
  labels:
    {{- include "app.labels" . | nindent 4 }}
spec:
  type: {{ .Values.service.type }}
  ports:
    - port: {{ .Values.service.port }}
      targetPort: http
      protocol: TCP
      name: http
  selector:
    {{- include "app.selectorLabels" . | nindent 4 }}
    app.kubernetes.io/component: {{ include "app.httpRole" . }}
"""

STORAGE_YAML = """\
{{- if and .Values.storage.local.enabled (not .Values.storage.local.existingClaim) }}
apiVersion: v1
kind: PersistentVolumeClaim
metadata:
  name: {{ include "app.fullname" . }}-storage
  labels:
    {{- include "app.labels" . | nindent 4 }}
spec:
  accessModes:
    - {{ .Values.storage.local.accessMode }}
  {{- with .Values.storage.local.storageClass }}
  storageClassName: {{ . }}
  {{- end }}
  resources:
    requests:
      storage: {{ .Values.storage.local.size }}
{{- end }}
"""

LAYA_YAML = """\
{{- if (.Values.laya).enabled }}
apiVersion: apps/v1
kind: Deployment
metadata:
  name: {{ include "app.fullname" . }}-laya
  labels:
    {{- include "app.labels" . | nindent 4 }}
    app.kubernetes.io/component: laya
spec:
  replicas: {{ .Values.laya.replicaCount }}
  selector:
    matchLabels:
      {{- include "app.selectorLabels" . | nindent 6 }}
      app.kubernetes.io/component: laya
  template:
    metadata:
      labels:
        {{- include "app.selectorLabels" . | nindent 8 }}
        app.kubernetes.io/component: laya
    spec:
      securityContext:
        runAsNonRoot: true
      containers:
        - name: laya
          image: "{{ .Values.laya.image.repository }}:{{ .Values.laya.image.tag }}"
          imagePullPolicy: {{ .Values.laya.image.pullPolicy }}
          ports:
            - name: http
              containerPort: 8000
              protocol: TCP
          env:
            {{- range $key, $value := .Values.laya.env }}
            - name: {{ $key }}
              value: {{ $value | quote }}
            {{- end }}
            {{- if .Values.existingSecret }}
            - name: LAYA_API_KEY
              valueFrom:
                secretKeyRef:
                  name: {{ .Values.existingSecret }}
                  key: LAYA_API_KEY
                  optional: true
            {{- end }}
          readinessProbe:
            httpGet:
              path: /health
              port: http
            initialDelaySeconds: 30
            periodSeconds: 10
          livenessProbe:
            httpGet:
              path: /health
              port: http
            initialDelaySeconds: 120
            periodSeconds: 20
          resources:
            {{- toYaml .Values.laya.resources | nindent 12 }}
---
apiVersion: v1
kind: Service
metadata:
  name: {{ include "app.fullname" . }}-laya
  labels:
    {{- include "app.labels" . | nindent 4 }}
    app.kubernetes.io/component: laya
spec:
  type: ClusterIP
  ports:
    - port: 8000
      targetPort: http
      protocol: TCP
      name: http
  selector:
    {{- include "app.selectorLabels" . | nindent 4 }}
    app.kubernetes.io/component: laya
{{- end }}
"""

NOTES_TXT = """\
The tuvl engine is deploying in production mode.

Check the rollout:
  kubectl rollout status deployment/{{ include "app.fullname" . }}
{{- if .Values.split }}
  kubectl rollout status deployment/{{ include "app.fullname" . }}-worker
{{- end }}

Reach it locally:
  kubectl port-forward svc/{{ include "app.fullname" . }} 8885:{{ .Values.service.port }}
  curl http://127.0.0.1:8885/health
{{- if (.Values.laya).enabled }}

Laya (decision model) loads its weights on start, about a minute:
  kubectl rollout status deployment/{{ include "app.fullname" . }}-laya
{{- end }}
"""
